/* config.h — HobbyOS port configuration for GNU mtools 4.0.49.
 *
 * Upstream, this file is generated by configure from config.h.in.  The port
 * keeps mtools' sources byte-identical and pins the configuration here, the
 * same way src/user/sed/config.h does for GNU sed and src/user/nano/config.h
 * for GNU nano.
 *
 * The port's feature choices, and why:
 *
 *   mcopy / mmd / mdel only   — the full upstream tree builds ONE multicall
 *                               "mtools" binary that dispatches on argv[0]
 *                               (mtools.c).  HobbyOS loads separate flat
 *                               binaries, each with its own _start, so the
 *                               port provides one tiny main per tool instead
 *                               (see mtools_port.h) and transcribes only the
 *                               shared engine objects those three commands
 *                               pull.
 *   no HAVE_ICONV_H           — charsetConv.c falls back to its own CP4xx/
 *                               CP8xx codepage tables (codepages.c) instead
 *                               of iconv(); bytes round-trip through
 *                               wchar-as-byte.  This is the "C locale on
 *                               FAT" correct answer for 8.3 + ASCII LFN
 *                               payloads.
 *   no HAVE_WCHAR_H           — wchar_t maps to unsigned char (sysincludes.h
 *                               does this when the macro is absent), so all
 *                               LFN building uses byte strings.  The sysroot
 *                               wchar.c exists but the staging/acceptance
 *                               payloads are ASCII; documented for wave 3.
 *   no HAVE_SYS_IOCTL_H       — no ioctl(2) in the HobbyOS sysroot.  The
 *                               regular-file code path in plain_io.c never
 *                               calls it (BLKFLSBUF arm is compiled out when
 *                               the macro is undefined) and devices.c's
 *                               INIT_NOOP fallback supplies a stub
 *                               init_geom for non-regular files.
 *   no termios / sgtty        — tty.c compiles with USE_RAWTERM undefined:
 *                               no raw-terminal toggling, prompts fall back
 *                               to plain stdio reads on /dev/tty absence.
 *   no OS_linux / no USE_XDF  — devices.c's per-OS geometry ioctl arms stay
 *                               compiled out; the generic INIT_NOOP
 *                               init_geom stub is what links.
 *   HAVE_GETTIME...
 *
 * Everything else is upstream's default: FAT12/16/32, VFAT LFN writing
 * (vfat.c + mk_direntry.c long-name writers + charsetConv), -i IMG image
 * files, the -D clash handling, mcopy -t/-n/-m/-o/-a, mmd -p, mdel -v.
 */

/* -- Package identity ------------------------------------------------ */

#define PACKAGE "mtools"
#define PACKAGE_NAME "GNU mtools"
#define PACKAGE_VERSION "4.0.49"
#define PACKAGE_STRING "GNU mtools 4.0.49"
#define PACKAGE_BUGREPORT "bug-mtools@gnu.org"
#define PACKAGE_TARNAME "mtools"
#define PACKAGE_URL "https://www.gnu.org/software/mtools/"

/* -- Feature gates --------------------------------------------------- */

/* HobbyOS scope: no iconv, no wchar, no termios, no ioctl, no xdf. */
/* #undef HAVE_ICONV_H */
/* #undef HAVE_WCHAR_H */
/* #undef HAVE_WCTYPE_H */
/* #undef HAVE_SYS_IOCTL_H */
/* #undef HAVE_TERMIOS_H */
/* #undef HAVE_SYS_TERMIOS_H */
/* #undef HAVE_TERMIO_H */
/* #undef HAVE_SYS_TERMIO_H */
/* #undef HAVE_SGTTY_H */
/* #undef USE_XDF */
/* #undef USE_FLOPPYD */
/* #undef HAVE_SYS_FLOPPY_H */
/* #undef HAVE_SYS_FDIO_H */
/* #undef HAVE_LIBCAM */
/* #undef HAVE_SCSI */
/* #undef HAVE_MNTENT_H */

/* No OS flavour is defined: devices.c's per-OS geometry sections all
 * compile out, leaving only the generic device table + the INIT_NOOP
 * init_geom stub. */
/* #undef OS_linux */
/* #undef OS_sunos */
/* #undef OS_solaris */
/* #undef OS_aix */
/* #undef OS_freebsd */
/* #undef OS_netbsd */
/* #undef OS_darwin */

/* -- Host type / sizes (aarch64-none-elf, LP64) ---------------------- */

#define SIZEOF_INT 4
#define SIZEOF_LONG 8
#define SIZEOF_OFF_T 8
#define SIZEOF_SIZE_T 8
#define SIZEOF_TIME_T 8
#define HAVE_LONG_LONG 1
#define HAVE_UINTPTR_T 1

/* HobbyOS off_t is 64-bit, so llong.h's MT_OFF_T = off_t branch is taken
 * and no lseek64/llseek layer is needed. */
/* #undef HAVE_LLSEEK */
/* #undef HAVE_LSEEK64 */
/* #undef HAVE_OFF64_T */
/* #undef HAVE_LOFF_T */
/* #undef HAVE_OFFSET_T */
/* #undef HAVE_LSEEK64_PROTOTYPE */
/* #undef HAVE_LLSEEK_PROTOTYPE */

