#define HAVE_SYS_TIME_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_SYS_WAIT_H 1
#define HAVE_TIME_H 1
#define HAVE_UNISTD_H 1
#define HAVE_UTIME_H 1

/* dirent exists (opendir/readdir are implemented; only used for
 * `mcopy -s` recursion, which is not part of the acceptance recipes). */
#define HAVE_DIRENT_H 1

/* pwd.h: getpwuid()/getpwnam() return a synthetic single user. */
#define HAVE_PWD_H 1

/* -- Function surface ------------------------------------------------ */

#define HAVE_ATEXIT 1
#define HAVE_GETOPT_LONG 1
#define HAVE_GETTIMEOFDAY 1
#define HAVE_SNPRINTF 1
#define HAVE_MKDIR 1
#define HAVE_STRCASECMP 1
#define HAVE_STRCHR 1
#define HAVE_STRCSPN 1
#define HAVE_STRDUP 1
#define HAVE_STRERROR 1
#define HAVE_STRINGS_H 1
#define HAVE_STRNCASECMP 1
#define HAVE_STRPBRK 1
#define HAVE_STRRCHR 1
#define HAVE_STRSPN 1
#define HAVE_STRSTR 1
#define HAVE_STRTOL 1
#define HAVE_STRTOLL 1
#define HAVE_STRTOUL 1
#define HAVE_STRNLEN 1
#define HAVE_UTIME 1
#define HAVE_SETLOCALE 1

/* missFuncs.c provides its own strndup (the sysroot does not have one
 * yet), so leave HAVE_STRNDUP undefined: sysincludes.h then declares it
 * and the port's missFuncs.o satisfies the symbol. */
/* #undef HAVE_STRNDUP */

/* No getuid/geteuid libc helpers beyond the sysroot's own */
/* #undef HAVE_SETEUID */
/* #undef HAVE_SETRESUID */
/* #undef HAVE_GETRESUID */

/* srand/rand only (sysincludes maps srandom/srand48/lrand48 onto them). */
/* #undef HAVE_SRAND48 */
/* #undef HAVE_LRAND48 */
/* #undef HAVE_SRANDOM */

/* No flock-based device locking in image mode (plain_io.c lock_dev arm);
 * lockdev.c detects the absence at compile time. */
/* #undef HAVE_FLOCK */
/* #undef HAVE_LOCKF */
/* #undef HAVE_FCNTL */

/* No tzset() beyond the sysroot's UTC-only time layer. */
/* #undef HAVE_TZSET */

/* -- Other upstream defaults we keep ---------------------------------- */

#define STDC_HEADERS 1
#define HAVE_MEMCPY 1
#define HAVE_MEMMOVE 1
#define HAVE_MEMSET 1

/* mtools uses `access()` via unistd; the sysroot has it. */
#define HAVE_ACCESS 1

/* ================= HobbyOS glue =================
 * mtools' upstream sources expect a glibc-ish POSIX surface that the
 * HobbyOS sysroot does not fully expose yet.  Rather than patch upstream
 * files, this block declares the missing entry points here (config.h is
 * included by every TU via sysincludes.h); the implementations live in
 * mtools_port.c, the port's first-party glue file (same role as nano's
 * hb_curses.c).  Nothing here changes mtools behavior for the ported
 * image-file subset; all of it is uninhabited fallback.
 *
 * The whole block is guarded by HOBBYOS_TARGET so the SAME transcription
 * builds on a host (for the parity harness / reference races, where glibc
 * provides every one of these symbols).  The host build defines nothing
 * special; the OS build adds -DHOBBYOS_TARGET.
 */
#ifdef HOBBYOS_TARGET

/* gettimeofday(): the sysroot's sys/time.h omits the deprecated
 * `struct timezone`; mtools file.c passes one only to discard it.  The
 * sysroot's gettimeofday(tv, void*) ignores the second argument, so a
 * local struct with the glibc layout keeps file.c's timezone probe
 * compiling with identical semantics (tz_minuteswest stays 0 = UTC). */
#ifndef MTOOLS_PORT_TIMEZONE
#define MTOOLS_PORT_TIMEZONE
struct timezone { int tz_minuteswest; int tz_dsttime; };
#endif

/* uid_t/gid_t: sysroot sys/types.h defines both. */
#include <sys/types.h>

/* The sysroot implements fork/exec in libc.a but (unlike glibc) declares
 * them only in the HobbyOS umbrella <libc.h>, which mtools does not
 * include.  Nothing in the ported subset reaches fork at runtime (the
 * fork-based mkdir fallback in missFuncs.c is off via HAVE_MKDIR); these
 * declarations exist so the sysroot signatures stay visible if a future
 * trim re-enables the paths. */
int fork(void);

/* mkdir(): the sysroot implements the HobbyOS 1-arg shape
 * (int mkdir(const char*)).  mtools calls it with a mode argument; on
 * AArch64 the extra register argument is ignored by the callee, so a
 * varargs declaration matches the call sites and the runtime symbol. */
int mkdir(const char *path, ...);

/* getlogin()/alarm()/setuid()/setgid(): not in the sysroot; the port
 * provides fallbacks in mtools_port.c (single-user, no alarm). */
char *getlogin(void);
unsigned int alarm(unsigned int seconds);
int setuid(unsigned int uid);
int setgid(unsigned int gid);

#endif /* HOBBYOS_TARGET */

/* progname + helpFlag normally come from mtools.c's toplevel; the port
 * mains (mtools_port.c) own them instead, so the upstream stick needs
 * these everywhere (mtools.h already declares progname extern). */
int helpFlag(int argc, char **argv);

/* ================= HOST_TEST (parity harness) =================
 * The same transcription also builds on a host (the reference races that
 * prove the ported engine byte-identical against pristine).  A quoted
 * #include "config.h" from sysincludes.h resolves to THIS file even though
 * the harness passes -I for a generated host config, so this small block
 * retargets the features that differ between the sysroot and glibc:
 *
 *   - HAVE_TZSET + Linux (the normal host case): sysincludes.h undefines
 *     HAVE_GETTIMEOFDAY, so file.c's timezone probe uses tzset() and never
 *     needs the (deprecated) `struct timezone` that the HobbyOS glue block
 *     supplies.  The HobbyOS target keeps HAVE_GETTIMEOFDAY + the glue.
 *   - HAVE_STRNDUP on: glibc provides it; without this missFuncs.c would
 *     contribute its own strndup(), colliding at host link time.
 * Everything else in the pins above already holds on glibc.
 */
#ifdef HOST_TEST

#define HAVE_TZSET 1
#define HAVE_STRNDUP 1
/* glibc has a real readdir; unixdir.c only compiles its directory
 * recursion under HAVE_READDIR.  (The HobbyOS sysroot declares the same
 * API as ENOSYS stubs — L4 audit §4.2 — so the OS build intentionally
 * leaves it off; `mcopy -s` is not in the acceptance recipes.) */
#define HAVE_READDIR 1

#endif /* HOST_TEST */
